class TreeNode {
  constructor(val, left = null, right = null) {
    this.val = val; this.left = left; this.right = right;
  }
}

function heightImpl(node) {
  if (node === null) return -1;
  return 1 + Math.max(heightImpl(node.left), heightImpl(node.right));
}

function countNodesImpl(node) {
  if (node === null) return 0;
  return 1 + countNodesImpl(node.left) + countNodesImpl(node.right);
}

function isLeafImpl(node) {
  return node !== null && node.left === null && node.right === null;
}

function depthImpl(root, target, d = 0) {
  if (root === null) return -1;
  if (root.val === target) return d;
  const l = depthImpl(root.left, target, d + 1);
  return l !== -1 ? l : depthImpl(root.right, target, d + 1);
}

