  while (queue.length) {
    const sz = queue.length, level = [];
    for (let i = 0; i < sz; i++) {
      const node = queue.shift();
      level.push(node.val);
      if (node.left) queue.push(node.left);
      if (node.right) queue.push(node.right);
    }
    result.push(level);
  }
  return result;
