function rightSideViewImpl(root) {
  if (!root) return [];
  const result = [], queue = [root];
  while (queue.length) {
    const sz = queue.length;
    for (let i = 0; i < sz; i++) {
      const node = queue.shift();
      if (i === sz - 1) result.push(node.val);
      if (node.left) queue.push(node.left);
      if (node.right) queue.push(node.right);
    }
  }
  return result;
}

function zigzagLevelOrderImpl(root) {
  if (!root) return [];
  const result = [], queue = [root];
  let ltr = true;
  while (queue.length) {
    const sz = queue.length, level = new Array(sz);
    for (let i = 0; i < sz; i++) {
      const node = queue.shift();
      level[ltr ? i : sz - 1 - i] = node.val;
      if (node.left) queue.push(node.left);
      if (node.right) queue.push(node.right);
    }
    result.push(level);
    ltr = !ltr;
  }
  return result;
}

