class TreeNode {
  constructor(val, left = null, right = null) {
    this.val = val; this.left = left; this.right = right;
  }
}

function maxDepthUtil(root) {
  if (!root) return 0;
  return 1 + Math.max(maxDepthUtil(root.left), maxDepthUtil(root.right));
}

function isBalancedNaiveImpl(root) {
  if (!root) return true;
  const lH = maxDepthUtil(root.left);
  const rH = maxDepthUtil(root.right);
  if (Math.abs(lH - rH) > 1) return false;
  return isBalancedNaiveImpl(root.left) && isBalancedNaiveImpl(root.right);
}

function isBalancedImpl(root) {
  function dfsH(n) {
    if (!n) return -1;
    const l = dfsH(n.left); if (l === -2) return -2;
    const r = dfsH(n.right); if (r === -2) return -2;
    if (Math.abs(l - r) > 1) return -2;
    return 1 + Math.max(l, r);
  }
  return dfsH(root) !== -2;
}

function isBalancedCleanImpl(root) {
  function dfs(n) {
    if (!n) return { height: -1, balanced: true };
    const left = dfs(n.left);
    if (!left.balanced) return { height: 0, balanced: false };
    const right = dfs(n.right);
    if (!right.balanced) return { height: 0, balanced: false };
    const balanced = Math.abs(left.height - right.height) <= 1;
    return { height: 1 + Math.max(left.height, right.height), balanced };
  }
  return dfs(root).balanced;
}

function allThreeAgree(root) {
  const a = isBalancedNaiveImpl(root);
  const b = isBalancedImpl(root);
  const c = isBalancedCleanImpl(root);
  return a === b && b === c;
}

