class TreeNode {
  constructor(val, left = null, right = null) {
    this.val = val; this.left = left; this.right = right;
  }
}

function hasPathSumImpl(root, targetSum) {
  if (!root) return false;
  if (!root.left && !root.right) return root.val === targetSum;
  return hasPathSumImpl(root.left, targetSum - root.val) ||
         hasPathSumImpl(root.right, targetSum - root.val);
}

function pathSumImpl(root, targetSum) {
  const result = [];
  function dfs(node, remaining, path) {
    if (!node) return;
    path.push(node.val);
    if (!node.left && !node.right && remaining === node.val) {
      result.push([...path]);
    }
    dfs(node.left, remaining - node.val, path);
    dfs(node.right, remaining - node.val, path);
    path.pop();
  }
  dfs(root, targetSum, []);
  return result;
}

function pathSumIIIImpl(root, targetSum) {
  const prefixCounts = new Map([[0, 1]]);
  let count = 0;
  function dfs(node, currentSum) {
    if (!node) return;
    currentSum += node.val;
    count += prefixCounts.get(currentSum - targetSum) || 0;
    prefixCounts.set(currentSum, (prefixCounts.get(currentSum) || 0) + 1);
    dfs(node.left, currentSum);
    dfs(node.right, currentSum);
    prefixCounts.set(currentSum, prefixCounts.get(currentSum) - 1);
  }
  dfs(root, 0);
  return count;
}

