class TreeNode {
  constructor(val, left = null, right = null) {
    this.val = val; this.left = left; this.right = right;
  }
}

function classifyTreeTechnique(signals) {
  const s = new Set(signals);
  if (s.has('level_order') || s.has('right_side_view') || s.has('zigzag') || s.has('min_depth_level') || s.has('by_level')) return 'BFS';
  if (s.has('path_from_root') || s.has('depth_of_node') || s.has('path_sum')) return 'DFS Preorder';
  if (s.has('kth_smallest') || s.has('validate_bst') || s.has('sorted_output') || s.has('inorder')) return 'DFS Inorder';
  if (s.has('height') || s.has('diameter') || s.has('balanced') || s.has('subtree_count') || s.has('postorder')) return 'DFS Postorder';
  if (s.has('bst_search') || s.has('bst_insert') || s.has('bst_lca')) return 'BST Specific';
  return 'Unknown';
}

function solveBFS(root) {
  if (!root) return [];
  const result = [], queue = [root];
  while (queue.length) {
    const sz = queue.length, level = [];
    for (let i = 0; i < sz; i++) {
      const node = queue.shift();
      level.push(node.val);
      if (node.left) queue.push(node.left);
      if (node.right) queue.push(node.right);
    }
    result.push(level);
  }
  return result;
}

function solveDFSPreorder(root) {
  const sums = [];
  function dfs(node, currentSum) {
    if (!node) return;
    currentSum += node.val;
    if (!node.left && !node.right) sums.push(currentSum);
    dfs(node.left, currentSum);
    dfs(node.right, currentSum);
  }
  dfs(root, 0);
  return sums;
}

function solveDFSPostorder(root) {
  if (!root) return 0;
  return 1 + Math.max(solveDFSPostorder(root.left), solveDFSPostorder(root.right));
}

function solveBSTSpecific(root, val) {
  if (!root) return -1;
  if (root.val === val) return root.val;
  if (val < root.val) return solveBSTSpecific(root.left, val);
  return solveBSTSpecific(root.right, val);
}
